    ld.param.u64 %weight, [weight_ptr];
    ld.param.u64 %output, [output_ptr];
    ld.param.u32 %batch,  [batch];
    ld.param.u32 %in_c,   [in_c];
    ld.param.u32 %out_c,  [out_c];
    ld.param.u32 %H_in,   [H_in];
    ld.param.u32 %W_in,   [W_in];
    ld.param.u32 %H_out,  [H_out];
    ld.param.u32 %W_out,  [W_out];
    ld.param.u32 %K,      [K];

