    // Compute global thread id (1‑D grid)
    // --------------------------------------------------------------
    mov.u32 %tid, %tid.x;                           // threadIdx.x
    mul.lo.u32 %tmp, %blockIdx.x, %blockDim.x;      // blockIdx.x * blockDim.x
    add.u32 %tid, %tmp, %tid;                       // global linear id

    // --------------------------------------------------------------
    // Decode linear id to (b, oc, y, x)
    // --------------------------------------------------------------
    rem.u32 %x, %tid, %W_out;               // x = tid % W_out
    div.u32 %tmp, %tid, %W_out;             // tmp = tid / W_out

    rem.u32 %y, %tmp, %H_out;               // y = tmp % H_out
    div.u32 %tmp, %tmp, %H_out;             // tmp = tmp / H_out

