    // Main loops: ic, ky, kx
    // --------------------------------------------------------------
    mov.u32 %ic, 0;
IC_LOOP:
    setp.ge.u32 %p0, %ic, %in_c;
    @%p0 bra IC_DONE;

    mov.u32 %ky, 0;
KY_LOOP:
    setp.ge.u32 %p0, %ky, %K;
    @%p0 bra KY_DONE;

    // iy = y - ky
    sub.s32 %iy, %y, %ky;
    // if iy out of [0, H_in) skip
    setp.lt.s32 %p1, %iy, 0;
    setp.ge.u32 %p2, %iy, %H_in;
    or.pred %p1, %p1, %p2;
    @%p1 bra KY_NEXT;

    mov.u32 %kx, 0;
KX_LOOP:
    setp.ge.u32 %p0, %kx, %K;
    @%p0 bra KX_DONE;

