    // addr = ((b*in_c + ic)*H_in + iy)*W_in + ix
    // --------------------------------------------------------------
    mul.lo.u32 %addr, %b, %in_c;
    add.u32 %addr, %addr, %ic;
    mul.lo.u64 %addr, %addr, %H_in;
    add.u64 %addr, %addr, %iy;
    mul.lo.u64 %addr, %addr, %W_in;
    add.u64 %addr, %addr, %ix;
    mul.lo.u64 %addr, %addr, 2;               // sizeof(fp16)
    add.u64 %addr, %input, %addr;
    ld.global.nc.f16 %h_in, [%addr];

    // --------------------------------------------------------------
    // Load weight element (FP16)
    // weight layout: (in_c, out_c, K, K)
    // addr = ((ic*out_c + oc)*K + ky)*K + kx
    // --------------------------------------------------------------
    mul.lo.u32 %addr, %ic, %out_c;
    add.u32 %addr, %addr, %oc;
    mul.lo.u64 %addr, %addr, %K;
    add.u64 %addr, %addr, %ky;
    mul.lo.u64 %addr, %addr, %K;
    add.u64 %addr, %addr, %kx;
    mul.lo.u64 %addr, %addr, 2;
    add.u64 %addr, %weight, %addr;
    ld.global.nc.f16 %h_w, [%addr];

    // --------------------------------------------------------------
    // FP16 -> FP32, multiply‑accumulate
    // --------------------------------------------------------------
    cvt.f32.f16 %f_in, %h_in;
    cvt.f32.f16 %f_w, %h_w;
    mul.f32 %prod, %f_in, %f_w;
    add.f32 %acc, %acc, %prod;

