    add.u32 %kx, %kx, 1;
    bra KX_LOOP;
KX_DONE:

KY_NEXT:
    add.u32 %ky, %ky, 1;
    bra KY_LOOP;
KY_DONE:

IC_NEXT:
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;
IC_DONE:

    // --------------------------------------------------------------
    // Store result (convert FP32 -> FP16)
    // addr = ((b*out_c + oc)*H_out + y)*W_out + x
    // --------------------------------------------------------------
    mul.lo.u32 %addr, %b, %out_c;
    add.u32 %addr, %addr, %oc;
    mul.lo.u64 %addr, %addr, %H_out;
    add.u64 %addr, %addr, %y;
    mul.lo.u64 %addr, %addr, %W_out;
    add.u64 %addr, %addr, %x;
    mul.lo.u64 %addr, %addr, 2;
    add.u64 %addr, %output, %addr;

    cvt.f16.f32 %h_in, %acc;          // reuse %h_in as temporary
    st.global.f16 [%addr], %h_in;

DONE:
    ret;
